types.01_SceIoStat:
typedef struct {
    u16 year; /* 0x0 */
    u16 month; /* 0x2 */
    u16 day; /* 0x4 */
    u16 hour; /* 0x6 */
    u16 minute; /* 0x8 */
    u16 second; /* 0xA */
    u32 microsecond; /* 0xC */
} ScePspDateTime;

/* 0x58 bytes */
struct SceIoStat {
    SceMode st_mode; /* 0x0 */
    u32 st_attr; /* 0x4 */
    SceOff st_size; /* 0x8 */
    ScePspDateTime st_ctime; /* 0x10 */
    ScePspDateTime st_atime; /* 0x20 */
    ScePspDateTime st_mtime; /* 0x30 */
    u32 st_private[6]; /* 0x40 */
};

types.11_LFlashSegment:
typedef struct LFlashSegment LFlashSegment;
/* lflash segment, 0x1C bytes */
struct LFlashSegment {
    u8 pad0[0x4];
    u16 firstLbn; /* 0x4 */
    u8 pad6[0x2];
    u16 maxLbn; /* 0x8 */
    u8 padA[0x2];
    u16 *lpTable; /* 0xC */
    u8 pad10[0xC];
};

types.12_LFlashDev:
