/* lflash device state (D_0000EED0), 1.00: 0x1C8 bytes */
struct LFlashDev {
    u8 pad0[0x18C];
    u32 pageSize; /* 0x18C */
    s32 pageShift; /* 0x190 */
    u32 pagesPerBlock; /* 0x194 */
    u8 pad198[0x14];
